const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const escapeHtml=s=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const t=key=>String((UI[state.uiLang]||UI.tr)[key]||UI.tr[key]||key).replace(/Clara/g,CHARACTERS[state.character]?.name||'Clara');
const PROFILE_KEY='sprechraumStudentProfiles',CURRENT_PROFILE_KEY='sprechraumCurrentStudent';
let studentProfiles=[],profileDraftId=null;
function loadStudentProfiles(){try{studentProfiles=JSON.parse(localStorage.getItem(PROFILE_KEY)||'[]')}catch{studentProfiles=[]}if(!studentProfiles.length){studentProfiles=[{id:`p-${Date.now()}`,name:'İlyas',age:'',origin:'',city:'',job:'',languages:'',goal:'',facts:{},progress:{sessions:0,scores:[],events:[],activeDays:[]},createdAt:new Date().toISOString()}];localStorage.setItem(PROFILE_KEY,JSON.stringify(studentProfiles))}let id=localStorage.getItem(CURRENT_PROFILE_KEY);if(!studentProfiles.some(x=>x.id===id))id=studentProfiles[0].id;localStorage.setItem(CURRENT_PROFILE_KEY,id)}
function currentStudent(){return studentProfiles.find(x=>x.id===localStorage.getItem(CURRENT_PROFILE_KEY))||studentProfiles[0]}
function saveStudentProfiles(){localStorage.setItem(PROFILE_KEY,JSON.stringify(studentProfiles))}
function studentInitials(name){return String(name||'Öğrenci').trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toLocaleUpperCase('tr-TR')).join('')}
function studentMemoryBrief(){const s=currentStudent(),facts={name:s.name,age:s.age||s.facts?.age,origin:s.origin||s.facts?.origin,city:s.city||s.facts?.city,job:s.job||s.facts?.job,languages:s.languages||s.facts?.languages,goal:s.goal||s.facts?.goal,family:s.facts?.family,leisure:s.facts?.leisure};return Object.entries(facts).filter(([,v])=>v).map(([k,v])=>`${k}: ${v}`).join('; ')}
function applyStudentUI(){const s=currentStudent();if(!s)return;$('#profileName').textContent=s.name;$('#profileAvatar').textContent=studentInitials(s.name);$('#profileStreak').textContent=`${s.progress?.sessions||0} çalışma · yerel hafıza`;$('#heroGreeting').textContent=`Hallo ${s.name}!`;if(state.view==='home')$('#pageTitle').textContent=`Guten Morgen, ${s.name}.`;renderProgress();window.SprechraumExamCenter?.syncStudent()}
function fillProfileForm(s){$('#studentName').value=s?.name||'';$('#studentAge').value=s?.age||s?.facts?.age||'';$('#studentOrigin').value=s?.origin||s?.facts?.origin||'';$('#studentCity').value=s?.city||s?.facts?.city||'';$('#studentJob').value=s?.job||s?.facts?.job||'';$('#studentLanguages').value=s?.languages||s?.facts?.languages||'';$('#studentGoal').value=s?.goal||s?.facts?.goal||'';const count=Object.values(s?.facts||{}).filter(Boolean).length,events=s?.progress?.events?.length||0;$('#profileMemoryPreview').textContent=s?`Clara bu öğrenci hakkında ${count} bilgi hatırlıyor. Öğrenme günlüğünde ${events} kayıt var.`:'Yeni öğrenci için ayrı bir hafıza oluşturulacak.'}
function openProfileDialog(){const s=currentStudent();profileDraftId=s.id;$('#profileSelect').innerHTML=studentProfiles.map(x=>`<option value="${escapeHtml(x.id)}" ${x.id===s.id?'selected':''}>${escapeHtml(x.name)}</option>`).join('');fillProfileForm(s);$('#profileDialog').showModal()}
function saveProfileFromForm(){const name=$('#studentName').value.trim();if(!name){toast('Lütfen öğrenci adını yazın.');return}let s=studentProfiles.find(x=>x.id===profileDraftId);if(!s){s={id:`p-${Date.now()}`,facts:{},progress:{sessions:0,scores:[],events:[],activeDays:[]},createdAt:new Date().toISOString()};studentProfiles.push(s)}Object.assign(s,{name,age:$('#studentAge').value.trim(),origin:$('#studentOrigin').value.trim(),city:$('#studentCity').value.trim(),job:$('#studentJob').value.trim(),languages:$('#studentLanguages').value.trim(),goal:$('#studentGoal').value.trim()});s.facts={...(s.facts||{}),age:s.age||s.facts?.age,origin:s.origin||s.facts?.origin,city:s.city||s.facts?.city,job:s.job||s.facts?.job,languages:s.languages||s.facts?.languages,goal:s.goal||s.facts?.goal};localStorage.setItem(CURRENT_PROFILE_KEY,s.id);saveStudentProfiles();$('#profileDialog').close();applyStudentUI();toast(`${s.name} için kişisel hafıza hazır.`)}
function learnStudentFacts(text){const s=currentStudent();if(!s)return;const raw=String(text),facts={...(s.facts||{})},take=(key,re)=>{const v=raw.match(re)?.[1]?.trim().replace(/[,.!?]+$/,'');if(v&&v.length<80&&!/[.…]/.test(v))facts[key]=v};take('name',/(?:mein name ist|ich hei(?:ß|ss)e)\s+([A-ZÄÖÜa-zäöüßÀ-ÖØ-öø-ÿ-]+)/i);take('age',/ich bin\s+(\d{1,3})\s+jahre alt/i);take('origin',/ich komme(?: ursprünglich)? aus\s+([^,.]+?)(?:\s+und\s+bin|[.!?]|$)/i);take('city',/(?:ich wohne|ich lebe|zurzeit wohne ich)(?:\s+in)?\s+([^,.!?]+)/i);take('job',/(?:von beruf bin ich|ich arbeite als)\s+([^,.!?]+)/i);take('languages',/(?:meine muttersprache ist|ich spreche)\s+([^.!?]+)/i);take('family',/(ich bin (?:verheiratet|ledig|geschieden)[^.!?]*|ich habe [^.!?]*(?:kind|sohn|tochter)[^.!?]*)/i);take('leisure',/(?:in meiner freizeit|mein hobby ist)\s+([^.!?]+)/i);take('goal',/(ich lerne deutsch,? weil\s+[^.!?]+|mein ziel ist\s+[^.!?]+)/i);s.facts=facts;if(facts.name&&!s.name)s.name=facts.name;saveStudentProfiles();applyStudentUI()}
function recordLearningEvent(type,details={}){const s=currentStudent();if(!s)return;const p=s.progress||{sessions:0,scores:[],events:[],activeDays:[]},day=new Date().toISOString().slice(0,10);p.sessions=(p.sessions||0)+1;p.events=[{type,date:new Date().toISOString(),...details},...(p.events||[])].slice(0,80);p.activeDays=[...new Set([...(p.activeDays||[]),day])].slice(-120);if(Number.isFinite(Number(details.score)))p.scores=[...(p.scores||[]),Number(details.score)].slice(-30);s.progress=p;saveStudentProfiles();applyStudentUI()}
function lessonSkillCategory(step={}){const id=String(step.id||step.step||'');if(id==='greeting')return'Selamlaşma';if(id==='wann')return'Zaman sorma';if(id==='wo'||id==='wohin')return'Yer ve yön';if(id==='wie')return'Yöntem ve ulaşım';if(id==='was')return'İçerik ve ihtiyaç';if(id==='wer')return'Görev paylaşımı';if(id==='proposal')return'Öneri yapma';if(id==='reaction')return'Tepki ve alternatif';if(id==='summary')return'Kararı özetleme';if(id==='closing')return'Kapanış';if(id.startsWith('task-'))return'Tema görevleri';return step.title||'Gemeinsam etwas planen'}
function rememberPlanningLesson(lesson){const student=currentStudent();if(!student||lesson.memorySaved)return;const progress=student.progress||(student.progress={sessions:0,scores:[],events:[],activeDays:[]}),examPrep=progress.examPrep||(progress.examPrep={version:1,categories:{},weakPhrases:[],lessonsCompleted:0,lastUpdated:null,syncReady:true}),now=new Date().toISOString();for(const result of lesson.phraseResults||[]){const category=result.category||lessonSkillCategory(result),entry=examPrep.categories[category]||(examPrep.categories[category]={practised:0,independent:0,supported:0,errors:0,lastPractised:null});entry.practised++;if(result.supported){entry.supported++;entry.errors++}else entry.independent++;entry.lastPractised=now;if(result.supported&&result.phrase){const key=lessonSpeechTokens(result.phrase).join(' '),existing=examPrep.weakPhrases.find(item=>item.key===key);if(existing){existing.errors++;existing.lastSeen=now;existing.stepTitle=result.stepTitle||existing.stepTitle}else examPrep.weakPhrases.push({key,phrase:result.phrase,category,stepTitle:result.stepTitle||category,errors:1,reviewed:0,lastSeen:now})}}
examPrep.weakPhrases=examPrep.weakPhrases.sort((a,b)=>b.errors-a.errors).slice(0,80);examPrep.lessonsCompleted=(examPrep.lessonsCompleted||0)+1;examPrep.lastUpdated=now;lesson.memorySaved=true;saveStudentProfiles()}
function markWeakPhraseReviewed(item,correct=true){const student=currentStudent(),examPrep=student?.progress?.examPrep;if(!examPrep||!item?.phrase)return;const key=lessonSpeechTokens(item.phrase).join(' '),stored=examPrep.weakPhrases.find(value=>value.key===key);if(stored){stored.reviewed=(stored.reviewed||0)+1;stored.lastReviewed=new Date().toISOString();stored.lastReviewCorrect=!!correct}saveStudentProfiles();renderProgress()}
function rememberExamObservation(category,{correct=true,phrase='',correction='',stepTitle=''}={}){const student=currentStudent();if(!student)return;const progress=student.progress||(student.progress={sessions:0,scores:[],events:[],activeDays:[]}),examPrep=progress.examPrep||(progress.examPrep={version:1,categories:{},weakPhrases:[],lessonsCompleted:0,lastUpdated:null,syncReady:true}),now=new Date().toISOString(),entry=examPrep.categories[category]||(examPrep.categories[category]={practised:0,independent:0,supported:0,errors:0,lastPractised:null});entry.practised++;if(correct)entry.independent++;else{entry.supported++;entry.errors++;const target=correction||phrase;if(target){const key=lessonSpeechTokens(target).join(' '),stored=examPrep.weakPhrases.find(item=>item.key===key);if(stored){stored.errors++;stored.lastSeen=now}else examPrep.weakPhrases.push({key,phrase:target,original:phrase,category,stepTitle:stepTitle||category,errors:1,reviewed:0,lastSeen:now})}}entry.lastPractised=now;examPrep.lastUpdated=now;examPrep.weakPhrases=examPrep.weakPhrases.sort((a,b)=>b.errors-a.errors).slice(0,80);saveStudentProfiles()}
function rememberOralResult(part,result){const category=part==='vorstellen'?'Sich vorstellen':'Bildbeschreibung';for(const sentence of result?.sentences||[])rememberExamObservation(category,{correct:sentence.status!=='wrong',phrase:sentence.original,correction:sentence.corrected});for(const missing of result?.coverage?.missing||[])rememberExamObservation(`${category} · ${missing.label}`,{correct:false,phrase:'',correction:missing.example,stepTitle:missing.label});renderProgress()}
function profileFactExample(index){const s=currentStudent(),f=s?.facts||{},v=(key)=>s?.[key]||f[key];return [`Guten Tag. Mein Name ist ${s?.name||'…'}.`,v('age')?`Ich bin ${v('age')} Jahre alt.`:'Ich bin … Jahre alt.',v('origin')?`Ich komme aus ${v('origin')}.`:'Ich komme ursprünglich aus …',v('city')?`Ich wohne in ${v('city')}.`:'Zurzeit wohne ich in …',f.family||'Ich bin … und habe …',v('job')?`Von Beruf bin ich ${v('job')}.`:'Von Beruf bin ich …',v('languages')?`Ich spreche ${v('languages')}.`:'Meine Muttersprache ist …',f.leisure?`In meiner Freizeit ${f.leisure}.`:'In meiner Freizeit …',v('goal')||'Ich lerne Deutsch, weil … Vielen Dank.'][index]}
function renderProgress(){const s=currentStudent();if(!s||!$('#memoryCard'))return;const p=s.progress||{},scores=p.scores||[],avg=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):null,facts=Object.entries({Name:s.name,Alter:s.age||s.facts?.age,Herkunft:s.origin||s.facts?.origin,Wohnort:s.city||s.facts?.city,Beruf:s.job||s.facts?.job,Sprachen:s.languages||s.facts?.languages,Ziel:s.goal||s.facts?.goal}).filter(([,v])=>v),examPrep=p.examPrep||{},categories=Object.entries(examPrep.categories||{}).sort((a,b)=>(b[1].errors||0)-(a[1].errors||0)),weak=(examPrep.weakPhrases||[]).filter(item=>!item.lastReviewCorrect||item.reviewed<item.errors).slice(0,5);$('#progressTitle').textContent=`${s.name}, deine Entwicklung`;$('#statSessions').textContent=p.sessions||0;$('#statFacts').textContent=facts.length;$('#statAverage').textContent=avg?`${avg}/100`:'—';$('#statTrend').textContent=scores.length>1?`${scores[0]} → ${scores.at(-1)} puan`:'ilk sınav bekleniyor';$('#statDays').textContent=p.activeDays?.length||1;$('#memoryCard').innerHTML=`<h3>Claras Gedächtnis über ${escapeHtml(s.name)}</h3><p>Kişisel bilgiler ve sınavdaki güçlü/zayıf alanlar bu öğrenci profiline ayrı kaydedilir.</p><div class="memory-facts">${facts.length?facts.map(([k,v])=>`<span><b>${escapeHtml(k)}:</b> ${escapeHtml(v)}</span>`).join(''):'<span>İlk tanıtımından sonra bilgiler burada görünecek.</span>'}</div>${categories.length?`<section class="exam-prep-memory"><header><b>Sınava hazırlık ilerlemesi</b><small>${examPrep.lessonsCompleted||0} öğretmen dersi</small></header><div>${categories.map(([name,value])=>{const total=value.practised||1,success=Math.round((value.independent||0)/total*100);return `<article><span><b>${escapeHtml(name)}</b><small>${value.supported||0} destek · ${value.independent||0} bağımsız</small></span><em>${success}%</em><i><u style="width:${success}%"></u></i></article>`}).join('')}</div>${weak.length?`<aside><b>Clara’nın hatırladığı çalışma cümleleri</b>${weak.map(item=>`<span>${escapeHtml(item.phrase)}</span>`).join('')}</aside>`:'<aside><b>Harika!</b><span>Şu anda bekleyen hata tekrarı yok.</span></aside>'}</section>`:''}<div class="memory-history">${(p.events||[]).slice(0,5).map(e=>`<div><span>${escapeHtml(e.label||e.type)}</span><time>${new Date(e.date).toLocaleDateString(state.uiLang)}</time></div>`).join('')}</div>`}
