const PARTNER_STORE_KEY='sprechraumPartnerNetwork';
let partnerStore={visible:false,friends:['dilan'],requests:[],groups:[],chats:{},blocked:[],reported:[],activeChat:null,room:null},partnerMediaStream=null;
function loadPartnerStore(){try{partnerStore={...partnerStore,...JSON.parse(localStorage.getItem(PARTNER_STORE_KEY)||'{}')}}catch{}savePartnerStore()}
function savePartnerStore(){localStorage.setItem(PARTNER_STORE_KEY,JSON.stringify({...partnerStore,room:null,activeChat:null}))}
const partnerById=id=>PARTNER_PROFILES.find(x=>x.id===id);
const purposeLabel=x=>({exam:'Sınav partneri',practice:'Konuşma pratiği',daily:'Günlük konuşma'}[x]||x);
function partnerCard(p){const friend=partnerStore.friends.includes(p.id),sent=partnerStore.requests.includes(p.id);return `<article class="partner-card ${p.online?'online':''}"><div class="partner-card-head"><span class="partner-photo">${escapeHtml(studentInitials(p.name))}</span><span><b>${escapeHtml(p.name)} ${p.verified?'✓':''}</b><small>${escapeHtml(p.city)} · ${p.age} yaş</small></span><em class="partner-level">${escapeHtml(p.level)}</em></div><div class="partner-purpose">${p.goals.map(x=>`<span>${escapeHtml(purposeLabel(x))}</span>`).join('')}</div><p>${escapeHtml(p.bio)}</p><div class="partner-meta"><span>Sınav<b>${escapeHtml(p.exam)} · ${escapeHtml(p.examDate)}</b></span><span>Diller<b>${escapeHtml(p.languages.slice(0,2).join(', '))}</b></span><span>Uygunluk<b>${escapeHtml(p.availability)}</b></span><span>Durum<b>${p.online?'Şimdi çevrimiçi':'Bugün aktifti'}</b></span></div><div class="partner-card-actions"><button data-partner-profile="${p.id}">Profili gör</button>${friend?`<button class="sent" data-partner-chat="${p.id}">Mesaj</button><button class="primary-action" data-partner-practice="${p.id}">Pratik</button>`:`<button class="primary-action ${sent?'sent':''}" data-partner-request="${p.id}">${sent?'İstek gönderildi':'İstek gönder'}</button>`}</div></article>`}
function renderPartnerDiscovery(){if(!$('#partnerCatalog'))return;const q=$('#partnerSearch').value.trim().toLocaleLowerCase('tr-TR'),level=$('#partnerLevel').value,goal=$('#partnerGoal').value,exam=$('#partnerExam').value,lang=$('#partnerLanguage').value;const result=PARTNER_PROFILES.filter(p=>!partnerStore.blocked.includes(p.id)&&(!q||`${p.name} ${p.city} ${p.languages.join(' ')}`.toLocaleLowerCase('tr-TR').includes(q))&&(!level||p.level===level)&&(!goal||p.goals.includes(goal))&&(!exam||p.exam===exam)&&(!lang||p.languages.includes(lang)));$('#partnerResultCount').textContent=result.length;$('#partnerCatalog').innerHTML=result.length?result.map(partnerCard).join(''):'<div class="theme-loading">Filtrelerine uygun aktif partner bulunamadı.</div>';updatePartnerVisibility()}
function updatePartnerVisibility(){const b=$('#partnerVisibility');if(!b)return;b.classList.toggle('on',partnerStore.visible);b.querySelector('em').textContent=partnerStore.visible?'Açık':'Kapalı'}
function openPartnerProfile(id){const p=partnerById(id),friend=partnerStore.friends.includes(id);if(!p)return;$('#partnerProfileContent').innerHTML=`<div class="partner-profile-cover"></div><div class="partner-profile-main"><span class="partner-photo">${escapeHtml(studentInitials(p.name))}</span><h2>${escapeHtml(p.name)} ${p.verified?'✓':''}</h2><small>${escapeHtml(p.city)} · ${p.level} Almanca · ${p.online?'Şimdi çevrimiçi':'Bugün aktifti'}</small><div class="partner-purpose">${p.goals.map(x=>`<span>${escapeHtml(purposeLabel(x))}</span>`).join('')}</div><p>${escapeHtml(p.bio)}</p><div class="partner-profile-grid"><div><span>Gireceği sınav</span><b>${escapeHtml(p.exam)} ${escapeHtml(p.level)}</b></div><div><span>Sınav tarihi</span><b>${escapeHtml(p.examDate)}</b></div><div><span>Konuştuğu diller</span><b>${escapeHtml(p.languages.join(', '))}</b></div><div><span>Uygun zaman</span><b>${escapeHtml(p.availability)}</b></div></div><div class="partner-profile-actions">${friend?`<button data-partner-chat="${p.id}">Mesaj gönder</button><button class="primary-action" data-partner-practice="${p.id}">Sınav pratiği yap</button>`:`<button class="primary-action" data-partner-request="${p.id}">Arkadaşlık isteği gönder</button>`}</div><div class="partner-danger-actions"><button type="button" data-partner-report="${p.id}">◇ Profili bildir</button><button type="button" data-partner-block="${p.id}">⊘ Engelle</button></div></div>`;$('#partnerProfileDialog').showModal()}
function reportPartner(id){if(!partnerStore.reported.includes(id))partnerStore.reported.push(id);savePartnerStore();$('#partnerProfileDialog').close();toast('Profil inceleme listesine alındı. Gerçek sürümde moderasyon ekibine iletilir.')}
function blockPartner(id){if(!partnerStore.blocked.includes(id))partnerStore.blocked.push(id);partnerStore.friends=partnerStore.friends.filter(x=>x!==id);savePartnerStore();$('#partnerProfileDialog').close();renderPartnerHub();toast('Profil engellendi ve listelerinden kaldırıldı.')}
function addFriend(id){if(!partnerStore.friends.includes(id))partnerStore.friends.push(id);if(!partnerStore.requests.includes(id))partnerStore.requests.push(id);savePartnerStore();renderPartnerDiscovery();renderFriends();$('#partnerProfileDialog').open&&$('#partnerProfileDialog').close();toast('İstek gönderildi · demo eşleşmesinde kabul edildi.')}
function renderFriends(){if(!$('#friendList'))return;const friends=partnerStore.friends.map(partnerById).filter(Boolean);$('#friendCount').textContent=friends.length;$('#friendList').innerHTML=friends.length?friends.map(p=>`<article class="friend-row"><span class="partner-photo">${escapeHtml(studentInitials(p.name))}</span><span><b>${escapeHtml(p.name)} · ${p.level}</b><small>${escapeHtml(p.city)} · ${p.online?'çevrimiçi':'çevrimdışı'}</small></span><div class="friend-row-actions"><button data-partner-chat="${p.id}">Mesaj</button><button data-partner-audio="${p.id}">Sesli ara</button><button data-partner-video="${p.id}">Görüntülü ara</button><button data-partner-practice="${p.id}">Sınav pratiği</button></div></article>`).join(''):'<div class="theme-loading">Henüz arkadaşın yok. Partner arama bölümünden istek gönderebilirsin.</div>';$('#friendActivity').innerHTML=friends.length?`<b>${friends.length} çalışma partnerin hazır</b><button data-partner-practice="${friends[0].id}">▶ ${escapeHtml(friends[0].name)} ile sınav pratiği</button><button data-partner-chat="${friends[0].id}">Mesajları aç</button>`:'<small>Önce bir partnerle eşleş.</small>'}
function openPartnerChat(id){const p=partnerById(id);if(!p)return;partnerStore.activeChat=id;partnerStore.chats[id] ||= [{from:'them',text:`Hallo ${currentStudent()?.name||''}! Wollen wir diese Woche zusammen Deutsch üben?`}];$('#chatPartnerName').textContent=p.name;renderPartnerChat();$('#partnerChatDialog').showModal()}
function renderPartnerChat(){const list=partnerStore.chats[partnerStore.activeChat]||[];$('#partnerChatStream').innerHTML=list.map(x=>`<div class="partner-chat-message ${x.from==='me'?'me':''}">${escapeHtml(x.text)}</div>`).join('');$('#partnerChatStream').scrollTop=$('#partnerChatStream').scrollHeight}
function sendPartnerChat(){const input=$('#partnerChatInput'),text=input.value.trim(),id=partnerStore.activeChat;if(!text||!id)return;partnerStore.chats[id].push({from:'me',text});input.value='';renderPartnerChat();savePartnerStore();setTimeout(()=>{partnerStore.chats[id].push({from:'them',text:'Ja, gerne! Welche Prüfungsthemen möchtest du üben?'});renderPartnerChat();savePartnerStore()},500)}
function renderGroups(){if(!$('#groupList'))return;$('#groupList').innerHTML=partnerStore.groups.length?partnerStore.groups.map((g,i)=>`<article class="group-card"><h4>${escapeHtml(g.name)}</h4><p>${escapeHtml(g.goal)} · ${g.members.length+1} üye</p><div class="group-members"><i>${escapeHtml(studentInitials(currentStudent()?.name))}</i>${g.members.map(id=>`<i>${escapeHtml(studentInitials(partnerById(id)?.name))}</i>`).join('')}</div><button data-group-open="${i}">Grup sohbetini aç</button></article>`).join(''):'<div class="theme-loading">Henüz grubun yok. Arkadaşlarını aynı çalışma grubunda birleştirebilirsin.</div>'}
function openGroupDialog(){const friends=partnerStore.friends.map(partnerById).filter(Boolean);$('#groupFriendChoices').innerHTML='<legend>Arkadaşlarını seç</legend>'+friends.map(p=>`<label><input type="checkbox" value="${p.id}"> ${escapeHtml(p.name)} · ${p.level}</label>`).join('');$('#groupName').value='';$('#groupDialog').showModal()}
function saveGroup(){const name=$('#groupName').value.trim(),members=$$('#groupFriendChoices input:checked').map(x=>x.value);if(!name||!members.length){toast('Grup adı yaz ve en az bir arkadaş seç.');return}partnerStore.groups.push({name,members,goal:$('#groupGoal').value,createdAt:new Date().toISOString()});savePartnerStore();$('#groupDialog').close();renderGroups();toast('Çalışma grubu oluşturuldu.')}
function setPartnerTab(tab){$$('[data-partner-tab]').forEach(x=>x.classList.toggle('active',x.dataset.partnerTab===tab));$$('[data-partner-panel]').forEach(x=>x.classList.toggle('active',x.dataset.partnerPanel===tab));$('#partnerRoom').hidden=true;if(tab==='friends')renderFriends();if(tab==='groups')renderGroups()}
