function openPartnerRoom(id,kind='practice'){const p=partnerById(id);if(!p)return;$('#partnerProfileDialog').open&&$('#partnerProfileDialog').close();$('#partnerChatDialog').open&&$('#partnerChatDialog').close();$$('[data-partner-panel]').forEach(x=>x.classList.remove('active'));partnerStore.room={partnerId:id,userRole:'A',started:false,themeId:state.themes[0]?.id||'',taskIndex:0,turns:[],kind};renderPartnerRoom();if(!state.themes.length)loadThemes().then(()=>{partnerStore.room.themeId=state.themes[0]?.id||'';renderPartnerRoom()})}
function renderPartnerRoom(){const room=partnerStore.room,p=partnerById(room?.partnerId),root=$('#partnerRoom');if(!room||!p)return;root.hidden=false;const theme=state.themes.find(x=>x.id===room.themeId)||state.themes[0],tasks=theme?.tasks||[],a=room.userRole==='A'?currentStudent()?.name:p.name,b=room.userRole==='B'?currentStudent()?.name:p.name;root.innerHTML=`<div class="room-head"><div><small>CANLI A/B PRATİK ODASI</small><h3>${escapeHtml(p.name)} ile sınav pratiği</h3></div><button data-room-close>Odayı kapat ×</button></div><div class="room-stage"><div class="room-partners"><div class="room-video" data-room-video="A"><span class="partner-photo">${escapeHtml(studentInitials(a))}</span>${room.userRole==='A'?'<video id="localPartnerVideo" autoplay muted playsinline></video>':''}<footer><span>Partner A · ${escapeHtml(a)} · Başlatır</span><button class="role-claim ${room.userRole==='A'?'active':''}" data-room-role="A">${room.userRole==='A'?'✓ Sen A’sın':'A olmak istiyorum'}</button></footer></div><div class="room-video" data-room-video="B"><span class="partner-photo">${escapeHtml(studentInitials(b))}</span>${room.userRole==='B'?'<video id="localPartnerVideo" autoplay muted playsinline></video>':''}<footer><span>Partner B · ${escapeHtml(b)}</span><button class="role-claim ${room.userRole==='B'?'active':''}" data-room-role="B">${room.userRole==='B'?'✓ Sen B’sin':'B olmak istiyorum'}</button></footer></div></div><div class="room-coach"><div class="room-theme-select"><select id="roomThemeSelect">${state.themes.map(x=>`<option value="${escapeHtml(x.id)}" ${x.id===room.themeId?'selected':''}>${escapeHtml(x.title)}</option>`).join('')}</select><button data-room-start>${room.started?'Yeniden başlat':'Clara ile başla'}</button></div>${theme?`<div class="room-task"><small>THEMA · ${room.taskIndex+1}/${Math.max(1,tasks.length)}</small><h4>${escapeHtml(theme.title)}</h4><p>${escapeHtml(theme.description)}</p><ul>${tasks.map((x,i)=>`<li class="${i<room.taskIndex?'done':i===room.taskIndex?'current':''}">${i<room.taskIndex?'✓ ':''}${escapeHtml(x)}</li>`).join('')}</ul></div>`:''}<div class="room-clara">${room.started?`Clara: ${room.taskIndex===0?`Aufgabe: ${theme?.description||''} Partner A beginnt. ${tasks[0]||''}`:`Jetzt sprechen wir über: ${tasks[room.taskIndex]||'Abschluss'}`}`:'Tema ve A/B rolünü seç. Başlattığında Clara görevi sesli okuyacak.'}</div><div class="room-dialogue">${room.turns.map(x=>`<div class="room-line"><b>${escapeHtml(x.role)}:</b> ${escapeHtml(x.text)}</div>`).join('')}</div>${room.started?`<div class="partner-chat-compose"><input id="roomTalkInput" placeholder="${room.turns.length%2===0?'Partner A':'Partner B'} konuşuyor…"><button type="button" data-room-send>Gönder</button></div>`:''}<div class="room-actions"><button class="room-hint" data-room-hint>✦ Clara’dan örnek cümle</button><button class="room-media" data-room-media="audio">Mikrofon</button><button class="room-media" data-room-media="video">Kamera</button><button class="room-finish" data-room-finish>Pratiği değerlendir</button></div><div id="roomPrivateHint"></div></div></div>`;if(partnerMediaStream){const video=$('#localPartnerVideo');if(video)video.srcObject=partnerMediaStream}}
function startRoom(){const room=partnerStore.room;if(!room)return;room.themeId=$('#roomThemeSelect').value;room.started=true;room.taskIndex=0;room.turns=[];renderPartnerRoom();const theme=state.themes.find(x=>x.id===room.themeId);speak(`Aufgabe: ${theme?.description||''}. Partner A beginnt. ${theme?.tasks?.[0]||''}`)}
