function setMobileTaskSheet(open,restoreFocus=true){const sheet=$('#mobileTaskSheet'),summary=$('#mobileTaskSummary'),toggle=$('#mobileTaskDetailsToggle'),arrow=toggle?.querySelector('em i');if(!sheet||!summary||!toggle)return;const next=!!open&&mobilePracticeQuery.matches;sheet.hidden=!next;summary.setAttribute('aria-expanded',String(next));toggle.setAttribute('aria-expanded',String(next));if(arrow)arrow.textContent=next?'⌃':'⌄';if(!next&&restoreFocus&&mobilePracticeQuery.matches)toggle.focus({preventScroll:true})}
