function renderTaskCoachGuide(guide){const panel=$('#taskCoachPanel');if(!panel)return;const examples=[['ÖRNEK CÜMLE',guide.studentExample],['PARTNER BUNU SÖYLERSE',guide.partnerExample],['KABUL ETME',guide.acceptExample],['NAZİKÇE REDDETME + ALTERNATİF',guide.rejectExample]].filter(([,value])=>value);panel.hidden=false;panel.innerHTML=`<article class="task-coach-card"><header><span><small>CLARA İLE ÖĞREN</small><b>${escapeHtml(guide.title)}</b></span><em>${guide.guideIndex+1}/${guide.total}</em></header><p class="task-coach-explanation">${escapeHtml(guide.explanation)}</p><div class="task-coach-examples">${examples.map(([label,value])=>`<button type="button" data-guide-speak="${escapeHtml(value)}"><small>${label}</small><span>${escapeHtml(value)}</span><em>▶ Dinle</em></button>`).join('')}</div><div class="task-coach-patterns"><small>PDF KALIPLARI</small><div>${(guide.patterns||[]).map(value=>`<span>${escapeHtml(value)}</span>`).join('')}</div></div><form class="task-coach-question" data-task-question-form data-guide-index="${guide.guideIndex}"><label><span>Bu görev hakkında Clara’ya sor</span><input name="question" maxlength="500" autocomplete="off" placeholder="Örn. Bu öneriyi nazikçe nasıl reddederim?"></label><button type="submit">Clara’ya sor</button><div class="task-coach-answer" hidden></div></form><footer>${escapeHtml(guide.source||'PDF rehberi')}</footer></article>`;panel.scrollIntoView({block:'nearest',behavior:'smooth'})}
async function openTeachingTask(index){if(state.planMode!=='learn'||state.exam)return;const panel=$('#taskCoachPanel'),theme=state.themes.find(x=>x.id===state.selectedThemeId);if(!panel||!theme)return;$$('[data-teach-task-index]',$('#taskBrief')).forEach(button=>button.classList.toggle('active',Number(button.dataset.teachTaskIndex)===Number(index)));panel.hidden=false;panel.innerHTML='<div class="task-coach-loading">Clara bu görev için PDF kalıplarını hazırlıyor…</div>';try{const response=await fetch('/api/exam/task-guide',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({themeId:theme.id,guideIndex:Number(index),studentName:currentStudent()?.name})}),guide=await response.json();if(!response.ok)throw Error(guide.error||'Rehber hazırlanamadı');renderTaskCoachGuide(guide)}catch(error){panel.innerHTML=`<div class="task-coach-error">${escapeHtml(error.message)}</div>`}}
async function askTaskCoach(form){const input=form.elements.question,answer=form.querySelector('.task-coach-answer'),theme=state.themes.find(x=>x.id===state.selectedThemeId),question=input.value.trim();if(!theme||!question)return;form.classList.add('busy');answer.hidden=false;answer.textContent='Clara düşünüyor…';try{const response=await fetch('/api/exam/task-question',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({themeId:theme.id,guideIndex:Number(form.dataset.guideIndex),question,studentName:currentStudent()?.name,ollamaUrl:state.settings.url,model:state.settings.model})}),data=await response.json();if(!response.ok)throw Error(data.error||'Cevap hazırlanamadı');answer.innerHTML=`<b>Clara</b><p>${escapeHtml(data.answer)}</p><button type="button" data-guide-speak="${escapeHtml(data.example)}"><span>${escapeHtml(data.example)}</span><em>▶ Dinle</em></button>`}catch(error){answer.textContent=error.message}finally{form.classList.remove('busy')}}
function stopPlanningLesson(resetComposer=true){state.planningLesson={active:false,steps:[],step:0,attempts:0,phraseIndex:0,phraseResults:[],themeId:null,reviewActive:false,reviewItems:[],reviewIndex:0,reviewAttempts:0,reviewOffered:false,memorySaved:false};state.paused=false;state.resumeContinuous=false;updatePauseUI();$('#practiceLayout')?.classList.remove('lesson-active');if(resetComposer&&$('#chatInput'))setChatExamReady(false)}
