function toggleSessionPause(){if(!state.started&&!state.planningLesson.active&&!state.exam){toast('Önce oturumu başlatın.');return}state.paused=!state.paused;if(state.paused){state.resumeContinuous=state.continuousListening;state.continuousListening=false;stopRecognition(false);stopSpeech(false);clearInterval(state.timer);state.timer=null;$('#chatInput').disabled=true;$('#micBtn').disabled=true;$('#chatForm').classList.add('busy');setVoiceState('','Oturum duraklatıldı')}else{$('#chatInput').disabled=false;$('#micBtn').disabled=false;$('#chatForm').classList.remove('busy');if(state.started&&!state.timer)state.timer=setInterval(sessionTick,1000);setVoiceState('','Sıra sende');if(state.resumeContinuous){state.continuousListening=true;state.resumeContinuous=false;updateMicUI();setTimeout(()=>startRecognition(true),250)}}updatePauseUI();updateComposerSendState()}
function lessonStep(id,title,explanation,example,prompt,extra={}){return {id,title,explanation,example,prompt,...extra}}
function phraseStep(id,title,explanation,phrases,prompt,extra={}){return lessonStep(id,title,explanation,phrases[0],prompt,{...extra,kind:'repeat',phrases})}
function greetingPracticeStep(){const phrases=['Hallo! Wie geht es dir?','Mir geht es gut, danke. Und dir?','Schön, dich zu sehen. Lass uns anfangen.'],phraseLabels=['Selam ver ve hâlini sor','Cevap ver ve karşı soru sor','Doğal biçimde göreve geç'];return lessonStep('greeting','Begrüßung · cümleleri tekrar et',`Clara önce üç temel Begrüßung cümlesini Almanca okuyacak. “Sıra sende” dedikten sonra yanıp sönen cümleyi oku veya yaz. Doğru söylediğinde cümle yeşile dönecek ve sıradaki cümle açılacak.`,phrases[0],'Yanıp sönen cümleyi Almanca olarak oku veya yaz.',{kind:'repeat',phrases,phraseLabels,celebrate:true,source:'Redemittel · Begrüßung und Gesprächseinstieg'})}
function buildPlanningLesson(theme,guides){const name=currentStudent()?.name||'öğrenci',tasks=guides.map((guide,index)=>lessonStep(`task-${index}`,`${index+1}. tema görevi · ${guide.title}`,`${guide.explanation} Burada artık öğrendiğin kalıpları kullanarak Clara ile gerçek bir karar alacaksın.`,guide.studentExample,`Şimdi “${guide.title}” görevi için tam bir Almanca cümle kur.`,{kind:'task',guide,dialogue:[`A: ${guide.studentExample}`,`B: ${guide.partnerExample||guide.acceptExample}`]}));return [
lessonStep('orientation','Sınavı tanı',`Bu bölümde amaç kusursuz gramer değil; partnerinle plan yapmak ve ortak karara ulaşmaktır. Goethe B1 modelinde bu görev yaklaşık 3 dakika, telc B1 modelinde yaklaşık 6 dakikadır. Hazırlık ve toplam konuşma süresi sınav sağlayıcısına göre değişir. Öneri yapman, soru sorman, tepki vermen, ayrıntıları netleştirmen ve kararı özetlemen beklenir.`,'Hazırım, başlayalım.','Hazırsan “Hazırım, başlayalım” yaz veya söyle.',{kind:'ready',source:'Goethe B1 Modellsatz · telc Deutsch B1 Übungstest'}),
greetingPracticeStep(name),
phraseStep('wann','Wann? · zamanı sor',`“Wann?” günü veya zamanı sorar. Şimdi zamanla ilgili üç farklı soru kalıbını dinle ve sırayla tekrar et.`,['Wann sollen wir das machen?','Welcher Tag passt dir am besten?','Um wie viel Uhr wollen wir uns treffen?'],'İşaretli Wann cümlesini oku.'),
phraseStep('wo','Wo? · sabit yeri sor',`“Wo?” bir buluşmanın veya etkinliğin nerede olacağını sorar.`,['Wo wollen wir uns treffen?','Wo soll die Feier stattfinden?','Ist dieser Ort für dich gut erreichbar?'],'İşaretli Wo cümlesini oku.'),
phraseStep('wohin','Wohin? · hedefi sor',`“Wohin?” bir yere doğru hareketi veya gidilecek hedefi sorar. Wo ile karıştırma.`,['Wohin wollen wir fahren?','Wohin sollen wir am Wochenende gehen?','Wohin könnten wir gemeinsam einen Ausflug machen?'],'İşaretli Wohin cümlesini oku.'),
phraseStep('wie','Wie? · yöntem ve ulaşım',`“Wie?” nasıl yapacağınızı veya hangi ulaşımı kullanacağınızı netleştirir.`,['Wie kommen wir dorthin?','Wie wollen wir das organisieren?','Wie lange soll die Veranstaltung dauern?'],'İşaretli Wie cümlesini oku.'),
phraseStep('was','Was? · eşya ve etkinlik',`“Was?” ne yapılacağını veya ne gerektiğini sorar.`,['Was müssen wir mitbringen?','Was wollen wir dort machen?','Was brauchen wir noch?'],'İşaretli Was cümlesini oku.'),
phraseStep('wer','Wer? · kişi ve görev',`“Wer?” sorusu görev paylaşımında kullanılır. Planın sonunda kimin ne yapacağı belli olmalıdır.`,['Wer kann noch mithelfen?','Wer kümmert sich um die Getränke?','Wer übernimmt welche Aufgabe?'],'İşaretli Wer cümlesini oku.'),
phraseStep('proposal','Vorschlag · fikir sun',`Bu kalıplarla nazik ve doğal öneri yapabilirsin. Önce Clara’yı dinle, sonra beş kalıbı sırayla tekrar et.`,['Ich habe eine Idee.','Ich schlage vor, dass wir uns am Samstag treffen.','Wir könnten zusammen ein Geschenk kaufen.','Wie wäre es, wenn wir mit dem Zug fahren?','Was hältst du davon, wenn wir gemeinsam kochen?'],'İşaretli öneri cümlesini oku.',{source:'Redemittel: Vorschläge machen'}),
phraseStep('reaction','Reagieren · kabul, ret ve alternatif',`Sınavda yalnızca “ja” veya “nein” demek yerine fikre tepki ver. Reddediyorsan sebep ve yeni bir alternatif ekle.`,['Das ist eine gute Idee.','Damit bin ich einverstanden.','Ich bin nicht sicher, ob das eine gute Idee ist.','Das passt mir leider nicht, weil ich arbeiten muss.','Vielleicht könnten wir uns stattdessen am Sonntag treffen.'],'İşaretli tepki cümlesini oku.',{source:'Redemittel: zustimmen · ablehnen · Alternative anbieten'}),
...tasks,
phraseStep('summary','Zusammenfassen · kararı özetle',`Bütün görevleri konuştuktan sonra kararı zaman, yer ve görev paylaşımıyla özetle.`,['Also, dann steht fest: Wir treffen uns am Samstag um zehn Uhr.','Du kümmerst dich um die Getränke und ich besorge das Essen.','Haben wir noch etwas vergessen?'],'İşaretli özet cümlesini oku.'),
phraseStep('closing','Verabschiedung · doğal kapanış',`Partner kararı onayladıktan sonra uzatma. Kısa ve doğal bir kapanış yeterlidir.`,['Gut, dann machen wir das so.','Ich wünsche dir einen schönen Tag.','Bis Samstag. Tschüss!'],'İşaretli kapanış cümlesini oku.')]}
function lessonProgress(){const lesson=state.planningLesson,theme=state.themes.find(x=>x.id===lesson.themeId),items=lesson.steps.map((step,index)=>({label:step.title,done:index<lesson.step,current:index===lesson.step}));$('#taskBrief').innerHTML=`<section class="task-steps-only lesson-steps"><div class="task-stage-header"><span><small>ÖĞRETMEN DERSİ</small><b>${Math.min(lesson.step+1,lesson.steps.length)} / ${lesson.steps.length} adım</b></span><em>TÜRKÇE ANLATIM</em></div><div class="task-stage-track">${items.map(x=>`<i class="${x.done?'done':x.current?'current':''}"></i>`).join('')}</div><ul>${items.map((x,index)=>`<li class="${x.done?'done':x.current?'current':''}"><i>${x.done?'✓':x.current?'→':'○'}</i><span>${escapeHtml(x.label)}</span>${x.current?'<button type="button" data-lesson-action="repeat">Tekrar dinle</button>':''}</li>`).join('')}</ul></section>`;renderMobileTaskSummary(theme,items,{done:lesson.step,total:items.length});$('#taskProgressLabel').textContent=`${lesson.step} / ${items.length} adım`}
function lessonPhraseList(step){const lesson=state.planningLesson;if(!step.phrases?.length)return'';const greeting=step.id==='greeting',previewing=!!lesson.isPreviewing;return `<div class="lesson-phrase-practice ${greeting?'greeting-redemittel':''}"><header><small>${greeting?'3 TEMEL REDEMITTEL · DİNLE VE TEKRAR ET':'ÖNCE DİNLE · SONRA SIRAYLA TEKRAR ET'}</small><b>${previewing?Math.min((lesson.previewIndex??0)+1,step.phrases.length):Math.min(lesson.phraseIndex+1,step.phrases.length)} / ${step.phrases.length}</b></header>${step.phrases.map((value,index)=>{const active=!previewing&&index===lesson.phraseIndex,preview=previewing&&index===lesson.previewIndex,previewDone=previewing&&index<lesson.previewIndex;return `<button type="button" class="${index<lesson.phraseIndex?'done ':''}${active?'current ':''}${index===lesson.phraseIndex-1?'just-done':''}${active&&lesson.phraseError?'phrase-error ':''}${preview?'previewing ':''}${previewDone?'preview-done ':''}" data-lesson-listen="${escapeHtml(value)}"><i>${index<lesson.phraseIndex?'✓':index+1}</i><span>${step.phraseLabels?.[index]?`<small>${escapeHtml(step.phraseLabels[index])}</small>`:''}${escapeHtml(value)}</span><em>${preview?'Clara okuyor':previewDone?'Okundu':active?'Sıra sende':index<lesson.phraseIndex?'Tamamlandı':'Dinle'}</em></button>`}).join('')}</div>`}
function greetingRoundCard(step){const round=step.rounds?.[state.planningLesson.phraseIndex];if(!round)return'';return `<div class="lesson-live-dialogue"><header><span>CANLI PRATİK</span><b>${state.planningLesson.phraseIndex+1}/${step.rounds.length}</b></header><small>CLARA</small><p>${escapeHtml(round.clara)}</p><aside>${escapeHtml(round.goal)}</aside><button type="button" data-lesson-use="${escapeHtml(round.example)}"><small>TAKILIRSAN BU ÖRNEĞİ KULLAN</small><b>${escapeHtml(round.example)}</b><em>Dokun ve cevapla →</em></button></div>`}
function renderLessonStep({speakStep=true}={}){const lesson=state.planningLesson,step=lesson.steps[lesson.step];if(!lesson.active||!step)return finishPlanningLesson();lessonProgress();const guided=step.kind==='repeat'||step.kind==='greeting',target=guided?step.phrases[lesson.phraseIndex]:step.example,card=document.createElement('article');card.className='planning-lesson-card';card.dataset.lessonStep=step.id;card.innerHTML=`<header><span><small>CLARA · ÖĞRETMEN MODU</small><b>${escapeHtml(step.title)}</b></span><em>${lesson.step+1}/${lesson.steps.length}</em></header><p>${escapeHtml(step.explanation)}</p>${lessonPhraseList(step)}${step.kind==='greeting'?greetingRoundCard(step):''}${step.dialogue?.length?`<div class="lesson-dialogue"><small>ÖRNEK MİNİ DİYALOG</small>${step.dialogue.map(line=>`<p>${escapeHtml(line)}</p>`).join('')}</div>`:''}${!guided?`<button type="button" class="lesson-example" data-lesson-use="${escapeHtml(target)}"><small>BUNU SÖYLEYEREK DENE</small><b>${escapeHtml(target)}</b><em>Dokun ve cevapla →</em></button>`:''}<footer><p>${escapeHtml(step.prompt)}</p><div><button type="button" data-lesson-action="repeat">↻ ${guided?'Örnekleri ve Clara’yı dinle':'Tekrar anlat'}</button><button type="button" data-lesson-action="next">Bu dersi geç →</button></div></footer>${step.source?`<aside>${escapeHtml(step.source)}</aside>`:''}`;appendChatNode(card,{force:true});if(speakStep)speakLessonStep(step)}
const lessonPause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
function teacherSpeechParts(text){const quoted=String(text).split(/([„“"][^„“”"]+[“”"])/g).filter(Boolean),parts=[];for(const value of quoted){const clean=value.replace(/^[„“"]|[“”"]$/g,'').trim(),german=/\b(?:ich|wir|wie|wann|wohin|wo|was|wer|hallo|guten|das|du|sie|also|passt|könnten|schlage|leider|stattdessen|haben|machen|treffen|bringen|fahren)\b/i.test(clean);if(!clean)continue;if(german){parts.push({text:clean,lang:'de'});continue}for(const sentence of clean.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[clean])if(sentence.trim())parts.push({text:sentence.trim(),lang:'tr'})}return parts}
async function speakTeacherText(text){const parts=teacherSpeechParts(text);if(parts[0])await prefetchSpeech(parts[0].text,{lang:parts[0].lang,voice:parts[0].lang==='tr'?'F1':null});for(let index=0;index<parts.length;index++){const part=parts[index],next=parts[index+1];if(next)void prefetchSpeech(next.text,{lang:next.lang,voice:next.lang==='tr'?'F1':null});await speak(part.text,{resume:false,lang:part.lang,voice:part.lang==='tr'?'F1':null});await lessonPause(90)}}
async function speakLessonStep(step){await speakTeacherText(step.explanation);const lesson=state.planningLesson;if(!lesson.active||lesson.steps[lesson.step]!==step||state.paused)return;if(step.phrases?.length){lesson.isPreviewing=true;lesson.previewIndex=0;refreshLessonPracticeCard(step);await prefetchSpeech(step.phrases[0],{lang:'de'});for(let index=0;index<step.phrases.length;index++){if(state.paused||!lesson.active||lesson.steps[lesson.step]!==step)return;const next=step.phrases[index+1];if(next)void prefetchSpeech(next,{lang:'de'});lesson.previewIndex=index;refreshLessonPracticeCard(step);await speak(step.phrases[index],{resume:false,lang:'de'});await lessonPause(120)}lesson.isPreviewing=false;lesson.previewIndex=-1;refreshLessonPracticeCard(step);if(step.id==='greeting')await speak('Şimdi sıra sende. Yanıp sönen cümleyi oku veya yaz. Doğru olduğunda yeşile dönecek ve sıradaki cümle açılacak.',{resume:false,lang:'tr',voice:'F1'});else await speak('Sıra sende.',{resume:false,lang:'tr',voice:'F1'});return}if(step.example)await speak(step.example,{resume:false,lang:step.kind==='ready'?'tr':'de',voice:step.kind==='ready'?'F1':null})}
async function startPlanningLesson(themeId=state.selectedThemeId){const theme=state.themes.find(x=>x.id===themeId);if(!theme)return;stopRecognition(false);stopSpeech(false);state.exam=null;$('#themeStartBtn').hidden=true;$('#chatStream').innerHTML='';setMobileTaskSheet(false,false);setVoiceState('thinking','Türkçe öğretmen dersi hazırlanıyor');try{const total=theme.tasks.length+3,guides=await Promise.all(Array.from({length:total},async(_,guideIndex)=>{const response=await fetch('/api/exam/task-guide',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({themeId,guideIndex,studentName:currentStudent()?.name})}),data=await response.json();if(!response.ok)throw Error(data.error||'Ders rehberi hazırlanamadı');return data}));state.planningLesson={active:true,steps:buildPlanningLesson(theme,guides.slice(1,1+theme.tasks.length)),step:0,attempts:0,phraseIndex:0,phraseResults:[],themeId,reviewActive:false,reviewItems:[],reviewIndex:0,reviewAttempts:0,reviewOffered:false,memorySaved:false};$('#practiceLayout').classList.add('exam-active','lesson-active');$('#examHintButton').hidden=true;setChatExamReady(true);renderPlanModeTabs();if(!state.started){state.started=true;state.seconds=0;$('#sessionTimer').textContent='00:00';state.timer=setInterval(()=>{state.seconds++;$('#sessionTimer').textContent=`${String(Math.floor(state.seconds/60)).padStart(2,'0')}:${String(state.seconds%60).padStart(2,'0')}`},1000)}renderLessonStep()}catch(error){stopPlanningLesson();renderThemePreview(theme);toast(error.message||'Öğretmen dersi başlatılamadı.')}}
function lessonAnswerLooksLikeQuestion(text){return /\?|nasıl|neden|ne demek|anlamadım|açıklar|hangi kalıp|tekrar anlat/i.test(text)}
function lessonSpeechTokens(text){return String(text).toLocaleLowerCase('de-DE').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zäöüß0-9 ]/gi,' ').split(/\s+/).filter(Boolean)}
function repeatedPhraseAccepted(text,target){const heard=lessonSpeechTokens(text),expected=lessonSpeechTokens(target);if(!heard.length||!expected.length)return false;const hits=expected.filter(token=>heard.includes(token)).length,coverage=hits/expected.length,lengthRatio=Math.min(heard.length,expected.length)/Math.max(heard.length,expected.length);return coverage>=.68&&lengthRatio>=.58}
function planningLessonResult(step,phrase,extra={}){return {step:step.id,stepTitle:step.title,category:lessonSkillCategory(step),phrase,index:state.planningLesson.phraseIndex,...extra}}
function analyzeGreetingAnswer(text){const lesson=state.planningLesson,value=text.toLocaleLowerCase('de-DE'),slots={greeting:/(hallo|guten morgen|guten tag|grüß dich)/.test(value),reaction:/(schön|freut mich|dich auch|ebenfalls|gleichfalls)/.test(value),wellbeing:/(mir geht|es geht mir|sehr gut|ganz gut|nicht schlecht|leider nicht so gut)/.test(value),counter:/(und dir|wie geht es dir|wie geht's dir|wie geht es ihnen|und ihnen)/.test(value)},required=['wellbeing','counter'],memory=lesson.greetingParts||{};for(const key of Object.keys(slots))if(slots[key])memory[key]=true;lesson.greetingParts=memory;const missing=required.filter(key=>!memory[key]);let correction='';if(slots.reaction&&!/dich (?:auch )?zu sehen/.test(value))correction=`${slots.greeting?/guten morgen/.test(value)?'Guten Morgen, Clara! ':'Hallo, Clara! ':''}Schön, dich auch zu sehen.`;else if(slots.wellbeing&&slots.counter)correction='Mir geht es gut, danke. Und dir?';else if(slots.wellbeing)correction='Mir geht es gut, danke.';else if(slots.greeting)correction=/guten morgen/.test(value)?'Guten Morgen, Clara!':'Hallo, Clara!';return {complete:missing.length===0,matched:Object.values(slots).some(Boolean),missing,slots,memory,correction}}
function greetingPartialTurn(analysis){const name=currentStudent()?.name||'du',missing=analysis.missing;if(missing.includes('wellbeing')&&analysis.memory.reaction)return {de:'Schön, dich auch zu sehen. Wie geht es dir heute?',tr:'Tepkini anladım ve küçük gramer düzeltmesini gösterdim. Şimdi Clara’nın sorusuna nasıl olduğunu söyleyerek cevap ver.',suggestion:'Mir geht es gut, danke.'};if(missing.includes('wellbeing'))return {de:`Hallo, ${name}! Wie geht es dir heute?`,tr:'Selamlamanı anladım. Şimdi Clara’nın sorusuna nasıl olduğunu söyleyerek cevap ver.',suggestion:'Mir geht es gut, danke.'};if(missing.includes('counter'))return {de:'Das freut mich.',tr:'Cevabın uygun. Selamlaşmayı karşılıklı yapmak için şimdi Clara’ya kısa bir karşı soru sor.',suggestion:'Und dir?'};return {de:'Wie geht es dir heute?',tr:'Clara’nın hâl hatır sorusuna cevap ver.',suggestion:'Mir geht es gut, danke.'}}
function greetingAnswerAccepted(text,index=state.planningLesson.phraseIndex){return analyzeGreetingAnswer(text,index).complete}
function greetingQuestionReply(text){const value=text.toLocaleLowerCase('de-DE');if(/wie (?:geht|geht's) (?:es )?(?:dir|ihnen)/.test(value)||/und (?:dir|ihnen)/.test(value))return {de:'Mir geht es gut, danke.',tr:'Soruna cevap verdim. Şimdi sen de nasıl olduğunu tam bir cümleyle söyle ve bana karşı soru sor.'};if(/wie heißt du|wie ist dein name/.test(value))return {de:'Ich heiße Clara.',tr:'Bu soru anlaşılır ve selamlaşmayla ilgili. Şimdi hâl hatır sorarak konuşmayı sürdür.'};if(/bist du bereit|können wir anfangen|sollen wir anfangen|wollen wir anfangen/.test(value))return {de:'Ja, ich bin bereit. Wir können anfangen.',tr:'Bu soru konuşmayı göreve geçirmek için uygundur.'};return null}
async function askGreetingPartnerQuestion(text,step){const fallback={de:'Ja, das passt zu unserem Gespräch. Lass uns mit der Begrüßung weitermachen.',tr:'Sorun selamlaşmayla ilgili. Clara cevap verdi; şimdi bulunduğun konuşma turunu tam bir cümleyle tamamla.'};try{const theme=state.themes.find(x=>x.id===state.planningLesson.themeId)?.title||'Gemeinsam etwas planen',system=`Du bist Clara, eine freundliche B1-Prüfungspartnerin. Thema: ${theme}. Der Lernende übt gerade die Begrüßung vor einer gemeinsamen Planung. Beantworte eine thematisch passende deutsche Frage natürlich in höchstens zwei kurzen B1-Sätzen. Bleibe bei Begrüßung, Befinden oder Gesprächsbeginn. Nur JSON: {"answer":"deutsche Antwort"}.`,response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({system,message:text,ollamaUrl:state.settings.url,model:state.settings.model})}),data=await response.json(),answer=String(data.answer||data.response||data.speak||'').trim();return answer?{de:answer,tr:'Clara soruna cevap verdi. Şimdi aynı selamlaşma turunu kendi cümlenle tamamla.'}:fallback}catch{return fallback}}
function lessonAnswerAccepted(text,step){const value=text.toLocaleLowerCase('de-DE').trim(),words=value.split(/\s+/).filter(Boolean);if(step.kind==='repeat')return repeatedPhraseAccepted(text,step.phrases[state.planningLesson.phraseIndex]||step.example);if(step.kind==='greeting')return greetingAnswerAccepted(text);if(step.kind==='ready')return /hazır|başla|bereit|los/.test(value);if(step.kind==='summary')return /(also|steht fest|machen wir)/.test(value)&&words.length>=7;if(step.kind==='closing')return /(schönen tag|bis |tschüss|ciao|auf wiedersehen)/.test(value);if(step.kind==='task')return words.length>=5&&/(wir|ich|du|uns|sollen|können|könnten|möchte|wäre)/.test(value);return words.length>=4}
async function askPlanningLessonQuestion(text,step){const fallback=`Bu adımda tam bir Almanca cümle kuruyoruz. Şu örneği kullanabilirsin: “${step.example}”`;try{const system=`Sen Clara adlı kadın Almanca B1 öğretmenisin. Türkçe, kısa ve sabırlı anlat. Konu Gemeinsam etwas planen, tema: ${state.themes.find(x=>x.id===state.planningLesson.themeId)?.title}. Ders adımı: ${step.title}. Öğrencinin sorusunu doğrudan yanıtla. Almanca yazdığın her kalıbı mutlaka “Almanca cümle” biçiminde tırnak içine al; böylece ses motoru dili doğru değiştirebilir. En sonda yalnızca bir uygun Almanca örnek ver. PDF kalıpları: Ich schlage vor, dass wir; Wir könnten; Wie wäre es, wenn wir; Das passt mir leider nicht, weil; Vielleicht könnten wir stattdessen.`,response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({system,message:text,ollamaUrl:state.settings.url,model:state.settings.model})}),data=await response.json(),answer=String(data.response||data.answer||'').trim();return answer||fallback}catch{return fallback}}
async function evaluatePlanningLessonAnswer(text,step){const theme=state.themes.find(x=>x.id===state.planningLesson.themeId),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),7500);try{const response=await fetch('/api/lesson/evaluate',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({message:text,theme:theme?.title,step:step.title,example:step.example,ollamaUrl:state.settings.url,model:state.settings.model})}),data=await response.json();if(!response.ok)throw Error(data.error||'teacher offline');return data}catch{return null}finally{clearTimeout(timer)}}
function refreshLessonPracticeCard(step){const cards=$$(`[data-lesson-step="${step.id}"]`);cards.at(-1)?.remove();renderLessonStep({speakStep:false})}
function showLessonConfetti(){document.querySelector('.lesson-confetti-burst')?.remove();const burst=document.createElement('div');burst.className='lesson-confetti-burst';burst.innerHTML=`<div><span>🎉</span><b>Harikasın!</b><small>Begrüßung tamamlandı</small></div>${Array.from({length:30},(_,index)=>`<i style="--i:${index};--x:${(index%10-4.5)*22}px;--delay:${(index%6)*.04}s"></i>`).join('')}`;document.body.appendChild(burst);setTimeout(()=>burst.remove(),2100)}
async function sendGreetingPracticeAnswer(text,step){const lesson=state.planningLesson,round=step.rounds[lesson.phraseIndex];if(!round)return;const analysis=analyzeGreetingAnswer(text);if(analysis.complete){lesson.phraseResults.push(planningLessonResult(step,analysis.correction||text,{supported:lesson.attempts>0,attempts:lesson.attempts+1}));addMessage('ai',round.reply,'Selamlaşmayı doğal biçimde göreve bağladın.');lesson.phraseIndex++;lesson.attempts=0;lesson.greetingParts={};$('#chatForm').classList.remove('busy');updateComposerSendState();addMessage('ai','Begrüßung tamamlandı. Selam verdin, karşı soru sordun ve konuşmayı göreve bağladın.');lesson.step++;lesson.phraseIndex=0;renderLessonStep({speakStep:false});void (async()=>{await speak(round.reply,{resume:false,lang:'de'});await speak('Harika. Begrüßung bölümünü tamamladın.',{resume:false,lang:'tr',voice:'F1'});const nextStep=lesson.steps[lesson.step];if(nextStep)await speakLessonStep(nextStep)})();return}if(analysis.matched){const turn=greetingPartialTurn(analysis);if(analysis.correction&&lessonSpeechTokens(analysis.correction).join(' ')!==lessonSpeechTokens(text).join(' '))addAcceptedCorrection(analysis.correction);addMessage('ai',turn.de,turn.tr);const suggestion=document.createElement('button');suggestion.type='button';suggestion.className='lesson-inline-suggestion';suggestion.dataset.lessonUse=turn.suggestion;suggestion.innerHTML=`<small>SADECE EKSİK PARÇAYI EKLE</small><b>${escapeHtml(turn.suggestion)}</b>`;appendChatNode(suggestion,{force:true});lesson.attempts=0;$('#chatForm').classList.remove('busy');updateComposerSendState();await speak(turn.de,{resume:false,lang:'de'});await speak(turn.tr,{resume:true,lang:'tr',voice:'F1'});return}if(lessonAnswerLooksLikeQuestion(text)){if(/[çğıöşü]|nasıl|neden|ne demek|anlamadım|açıklar|hangi kalıp|tekrar/i.test(text.toLocaleLowerCase('tr-TR'))){const answer=await askPlanningLessonQuestion(text,step);addMessage('ai',answer);$('#chatForm').classList.remove('busy');updateComposerSendState();await speakTeacherText(answer);return}const reply=greetingQuestionReply(text)||await askGreetingPartnerQuestion(text,step);addMessage('ai',reply.de,reply.tr);$('#chatForm').classList.remove('busy');updateComposerSendState();await speak(reply.de,{resume:false,lang:'de'});await speak(reply.tr,{resume:true,lang:'tr',voice:'F1'});return}lesson.attempts++;const finalTry=lesson.attempts>=2,feedback=finalTry?'Söylemek istediğini henüz güvenle anlayamadım. Clara’nın sorusuna uyan kısa bir parçayı seçebilirsin.':'Bu cevap selamlaşmayla bağlantılı görünmüyor. Clara’nın son cümlesine cevap vererek konuşmaya dön.';addMessage('ai',feedback);const suggestion=document.createElement('button');suggestion.type='button';suggestion.className='lesson-inline-suggestion';suggestion.dataset.lessonUse=round.example;suggestion.innerHTML=`<small>${finalTry?'DESTEKLE DEVAM ET':'KONUŞMAYA DÖN'}</small><b>${escapeHtml(round.example)}</b>`;appendChatNode(suggestion,{force:true});$('#chatForm').classList.remove('busy');updateComposerSendState();await speak(feedback,{resume:false,lang:'tr',voice:'F1'});if(finalTry)await speak(round.example,{resume:true,lang:'de'})}
async function sendPlanningLessonAnswer(text){
  const lesson=state.planningLesson;
  if(!lesson.active)return;
  text=text.trim();
  if(!text)return;
  if(lesson.reviewActive)return sendMistakeReviewAnswer(text);
  const step=lesson.steps[lesson.step];
  if(!step)return;
  addMessage('user',text);
  $('#chatInput').value='';
  $('#chatForm').classList.add('busy');
  updateComposerSendState();
  if(step.kind==='greeting')return sendGreetingPracticeAnswer(text,step);
  if(step.kind!=='repeat'&&lessonAnswerLooksLikeQuestion(text)){
    const answer=await askPlanningLessonQuestion(text,step);
    addMessage('ai',answer);
    $('#chatForm').classList.remove('busy');
    updateComposerSendState();
    await speakTeacherText(answer);
    return;
  }
  let teacherReview=null;
  if(step.kind==='task'){
    setVoiceState('thinking','Clara cevabını inceliyor');
    teacherReview=await evaluatePlanningLessonAnswer(text,step);
    if(teacherReview?.correctionDe&&teacherReview.correctionDe.toLocaleLowerCase('de-DE')!==text.toLocaleLowerCase('de-DE'))addAcceptedCorrection(teacherReview.correctionDe);
    if(teacherReview&&!teacherReview.onTopic){
      const feedback=teacherReview.feedbackTr||'Söylediğini anladım; fakat şimdi sınav görevine dönelim.',redirect=teacherReview.redirectDe||step.example;
      addMessage('ai',feedback);
      const suggestion=document.createElement('button');
      suggestion.type='button';
      suggestion.className='lesson-inline-suggestion';
      suggestion.dataset.lessonUse=redirect;
      suggestion.innerHTML=`<small>GÖREVE DÖN · BUNU DİYEBİLİRSİN</small><b>${escapeHtml(redirect)}</b>`;
      appendChatNode(suggestion,{force:true});
      $('#chatForm').classList.remove('busy');
      updateComposerSendState();
      await speak(feedback,{resume:false,lang:'tr',voice:'F1'});
      await speak(redirect,{resume:false,lang:'de'});
      return;
    }
  }
  if(lessonAnswerAccepted(text,step)||teacherReview?.acceptable){
    if(step.kind==='repeat'){
      lesson.phraseResults.push(planningLessonResult(step,step.phrases[lesson.phraseIndex],{supported:lesson.attempts>0,attempts:lesson.attempts+1}));
      lesson.phraseIndex++;
      lesson.attempts=0;
      refreshLessonPracticeCard(step);
      if(lesson.phraseIndex<step.phrases.length){
        const target=step.phrases[lesson.phraseIndex];
        $('#chatForm').classList.remove('busy');
        updateComposerSendState();
        playLessonFeedbackTone('success');
        if(step.id==='greeting'){
          addMessage('ai','Doğru söyledin. Şimdi yanıp sönen sıradaki cümleyi oku.');
          await speak('Doğru. Şimdi sıradaki cümle.',{resume:false,lang:'tr',voice:'F1'});
          await speak(target,{resume:false,lang:'de'});
        }
        return;
      }
      $('#chatForm').classList.remove('busy');
      updateComposerSendState();
      playLessonFeedbackTone('success');
      if(step.celebrate){
        addMessage('ai',`Harikasın! ${step.phrases.length} cümlenin hepsini doğru tamamladın.`);
        showLessonConfetti();
        await speak('Harikasın! Begrüßung bölümünü tamamladın.',{resume:false,lang:'tr',voice:'F1'});
        await lessonPause(650);
      }else await lessonPause(320);
      lesson.step++;
      lesson.phraseIndex=0;
      renderLessonStep();
      return;
    }
    lesson.phraseResults.push(planningLessonResult(step,teacherReview?.correctionDe||text,{supported:lesson.attempts>0||!!teacherReview?.correctionDe,attempts:lesson.attempts+1,freeAnswer:true}));
    addMessage('ai',teacherReview?.feedbackTr||'Evet, bu cevap bu adım için uygun. Şimdi bir sonraki konuşma becerisine geçiyoruz.');
    lesson.step++;
    lesson.attempts=0;
    lesson.phraseIndex=0;
    $('#chatForm').classList.remove('busy');
    updateComposerSendState();
    setTimeout(()=>renderLessonStep(),280);
    return;
  }
  lesson.attempts++;
  const target=step.kind==='repeat'?step.phrases[lesson.phraseIndex]:step.example,finalTry=lesson.attempts>=2,feedback=teacherReview?.feedbackTr||(step.kind==='repeat'?(finalTry?'Henüz tam anlaşılmadı. Cümleyi Almanca sesle yeniden dinle. İstersen cümleye dokunarak destekle tamamlayabilirsin.':'Neredeyse oldu. Kelimeleri acele etmeden, yanıp sönen cümlenin tamamını yeniden oku.'):(finalTry?'Fikrini anladım. Cümlenin sınava uygun hâlini aşağıda verdim. Örneğe dokunarak tamamlayabilirsin.':'Cevabın bu konuşma amacını henüz tam karşılamıyor. Tam cümle kur ve partneri konuşmaya dahil et.'));
  if(step.kind==='repeat'&&finalTry){
    lesson.phraseError=true;
    refreshLessonPracticeCard(step);
    lesson.phraseError=false;
    playLessonFeedbackTone('error');
    addMessage('ai',`Bu kez doğru anlaşılmadı. Doğru okunuşu Clara’dan dinle: “${target}” Bu cümleyi destekli tamamlıyorum; sıradaki cümlede yeniden deneyeceksin.`);
    $('#chatForm').classList.remove('busy');
    updateComposerSendState();
    await speak('Bu kez doğru anlaşılmadı. Doğru okunuşu dinle.',{resume:false,lang:'tr',voice:'F1'});
    await speak(target,{resume:false,lang:'de'});
    lesson.phraseResults.push(planningLessonResult(step,target,{supported:true,pronunciationHelp:true,attempts:lesson.attempts}));
    lesson.phraseIndex++;
    lesson.attempts=0;
    refreshLessonPracticeCard(step);
    playLessonFeedbackTone('success');
    if(lesson.phraseIndex<step.phrases.length){
      return;
    }
    addMessage('ai',`Bölüm tamamlandı. ${step.phrases.length} cümleyi çalıştın; destek aldığın cümleyi daha sonra yeniden tekrar edebilirsin.`);
    if(step.celebrate)showLessonConfetti();
    await speak(step.celebrate?'Harikasın! Begrüßung bölümünü tamamladın.':'Bu bölümü tamamladın.',{resume:false,lang:'tr',voice:'F1'});
    await lessonPause(650);
    lesson.step++;
    lesson.phraseIndex=0;
    renderLessonStep();
    return;
  }
  if(step.kind==='repeat'){
    lesson.phraseError=true;
    refreshLessonPracticeCard(step);
    lesson.phraseError=false;
    playLessonFeedbackTone('error');
    addMessage('ai','Tekrar dene. Yanıp sönen cümleyi bir kez daha oku.');
    $('#chatForm').classList.remove('busy');
    updateComposerSendState();
    await speak('Tekrar dene.',{resume:false,lang:'tr',voice:'F1'});
    return;
  }
  addMessage('ai',feedback);
  const suggestion=document.createElement('button');
  suggestion.type='button';
  suggestion.className='lesson-inline-suggestion';
  suggestion.dataset.lessonUse=target;
  suggestion.innerHTML=`<small>${finalTry?'DESTEKLE TAMAMLA':'YENİDEN DENE'}</small><b>${escapeHtml(target)}</b>`;
  appendChatNode(suggestion,{force:true});
  $('#chatForm').classList.remove('busy');
  updateComposerSendState();
  await speak(feedback,{resume:false,lang:'tr',voice:'F1'});
  await speak(target,{resume:false,lang:'de'});
}
function handleLessonAction(action){const lesson=state.planningLesson;if(!lesson.active)return;if(action==='repeat')return speakLessonStep(lesson.steps[lesson.step]);if(action==='next'){const step=lesson.steps[lesson.step];if(step?.kind==='repeat')for(let index=lesson.phraseIndex;index<(step.phrases?.length||0);index++)lesson.phraseResults.push({...planningLessonResult(step,step.phrases[index],{supported:true,skipped:true,attempts:0}),index});else if(step)lesson.phraseResults.push(planningLessonResult(step,step.example,{supported:true,skipped:true,attempts:0}));lesson.step++;lesson.attempts=0;lesson.phraseIndex=0;renderLessonStep()}}
function lessonWeakItems(lesson=state.planningLesson){const seen=new Set;return (lesson.phraseResults||[]).filter(result=>result.supported&&result.phrase).filter(result=>{const key=lessonSpeechTokens(result.phrase).join(' ');if(seen.has(key))return false;seen.add(key);return true})}
function renderMistakeReviewCard(){const lesson=state.planningLesson,node=document.createElement('article');document.querySelector('#lessonMistakeReview')?.remove();node.id='lessonMistakeReview';node.className='lesson-mistake-review';node.innerHTML=`<header><span><small>KİŞİSEL HATA TEKRARI</small><b>Yalnızca zorlandığın cümleler</b></span><em>${Math.min(lesson.reviewIndex+1,lesson.reviewItems.length)} / ${lesson.reviewItems.length}</em></header><p>Cümleleri bir kez daha doğru biçimde oku. Yanıp sönen cümle sıra sende demektir.</p><div class="lesson-phrase-practice">${lesson.reviewItems.map((item,index)=>`<button type="button" class="${index<lesson.reviewIndex?'done ':''}${index===lesson.reviewIndex?'current ':''}${index===lesson.reviewIndex&&lesson.reviewError?'phrase-error ':''}" data-lesson-listen="${escapeHtml(item.phrase)}"><i>${index<lesson.reviewIndex?'✓':index+1}</i><span><small>${escapeHtml(item.category)}</small>${escapeHtml(item.phrase)}</span><em>${index<lesson.reviewIndex?'Tekrarlandı':index===lesson.reviewIndex?'Sıra sende':'Bekliyor'}</em></button>`).join('')}</div></article>`;appendChatNode(node,{force:true})}
async function startMistakeReview(){const lesson=state.planningLesson;document.querySelector('.lesson-review-offer')?.remove();lesson.reviewItems=lessonWeakItems(lesson);if(!lesson.reviewItems.length)return showPlanningLessonCompletion();lesson.reviewActive=true;lesson.reviewIndex=0;lesson.reviewAttempts=0;$('#chatInput').readOnly=false;renderMistakeReviewCard();updateComposerSendState();await speak('Şimdi sadece zorlandığın cümleleri bir kez daha çalışacağız.',{resume:false,lang:'tr',voice:'F1'});await speak(lesson.reviewItems[0].phrase,{resume:false,lang:'de'});await speak('Sıra sende.',{resume:false,lang:'tr',voice:'F1'})}
async function sendMistakeReviewAnswer(text){const lesson=state.planningLesson,item=lesson.reviewItems[lesson.reviewIndex];if(!item)return;addMessage('user',text);$('#chatInput').value='';$('#chatForm').classList.add('busy');updateComposerSendState();if(repeatedPhraseAccepted(text,item.phrase)){playLessonFeedbackTone('success');markWeakPhraseReviewed(item,true);lesson.reviewIndex++;lesson.reviewAttempts=0;lesson.reviewError=false;if(lesson.reviewIndex>=lesson.reviewItems.length){document.querySelector('#lessonMistakeReview')?.remove();lesson.reviewActive=false;$('#chatForm').classList.remove('busy');updateComposerSendState();addMessage('ai','Harika! Zorlandığın cümlelerin tamamını yeniden çalıştın.');await speak('Harika. Hata tekrarını tamamladın.',{resume:false,lang:'tr',voice:'F1'});return showPlanningLessonCompletion()}renderMistakeReviewCard();$('#chatForm').classList.remove('busy');updateComposerSendState();await speak(lesson.reviewItems[lesson.reviewIndex].phrase,{resume:false,lang:'de'});await speak('Sıra sende.',{resume:false,lang:'tr',voice:'F1'});return}lesson.reviewAttempts++;lesson.reviewError=true;renderMistakeReviewCard();playLessonFeedbackTone('error');$('#chatForm').classList.remove('busy');updateComposerSendState();if(lesson.reviewAttempts<2){await speak('Tekrar dene.',{resume:false,lang:'tr',voice:'F1'});await speak(item.phrase,{resume:false,lang:'de'});return}markWeakPhraseReviewed(item,false);lesson.reviewIndex++;lesson.reviewAttempts=0;lesson.reviewError=false;if(lesson.reviewIndex>=lesson.reviewItems.length){document.querySelector('#lessonMistakeReview')?.remove();lesson.reviewActive=false;addMessage('ai','Hata tekrarı tamamlandı. Bu cümle Clara’nın gelişim hafızasında çalışılacak alan olarak kalacak.');return showPlanningLessonCompletion()}renderMistakeReviewCard();await speak(lesson.reviewItems[lesson.reviewIndex].phrase,{resume:false,lang:'de'});await speak('Sıra sende.',{resume:false,lang:'tr',voice:'F1'})}
function showPlanningLessonCompletion(){const lesson=state.planningLesson;if(lesson.completionShown)return;lesson.completionShown=true;const theme=state.themes.find(x=>x.id===lesson.themeId),node=document.createElement('article'),weak=lessonWeakItems(lesson).length,independent=(lesson.phraseResults||[]).filter(result=>!result.supported).length,total=(lesson.phraseResults||[]).length,score=total?Math.round(independent/total*100):100;node.className='planning-lesson-result';node.innerHTML=`<header><small>ÖĞRETMEN DERSİ TAMAMLANDI</small><b>${escapeHtml(theme?.title||'Gemeinsam etwas planen')}</b></header><p>16 adımı tamamladın. ${weak?`${weak} cümle gelişim hafızana kaydedildi.`:'Bütün cümleleri bağımsız tamamladın.'} Sınava hazırlık ilerlemen güncellendi.</p><div><button type="button" data-lesson-result="exam">◉ Aynı temada sınava başla</button><button type="button" data-lesson-result="repeat">↻ Dersi tekrarla</button><button type="button" data-lesson-result="themes">☰ Tema değiştir</button></div>`;appendChatNode(node,{force:true});$('#chatInput').readOnly=true;updateComposerSendState();recordLearningEvent('Gemeinsam etwas planen',{label:`${theme?.title||'Tema'} · Öğretmen dersi`,score});speak('Harika. Öğretmen dersini tamamladın. Sınava hazırlık ilerlemen kaydedildi.',{resume:false,lang:'tr',voice:'F1'})}
function finishPlanningLesson(){const lesson=state.planningLesson;if(lesson.reviewOffered||lesson.completionShown)return;clearInterval(state.timer);state.timer=null;state.started=false;rememberPlanningLesson(lesson);lesson.reviewOffered=true;const weak=lessonWeakItems(lesson);if(!weak.length)return showPlanningLessonCompletion();const node=document.createElement('article');node.className='lesson-review-offer';node.innerHTML=`<span>↻</span><div><small>16 ADIM TAMAMLANDI</small><b>Yanlışlarını doğru şekilde tekrar etmek ister misin?</b><p>Yalnızca destek aldığın ${weak.length} cümle, tek bir kısa turda sırayla yanıp sönecek.</p></div><footer><button type="button" data-lesson-result="review">Evet, yanlışlarımı tekrar et</button><button type="button" data-lesson-result="skip-review">Şimdilik geç</button></footer>`;appendChatNode(node,{force:true});$('#chatInput').readOnly=true;updateComposerSendState();speak(`16 adımı tamamladın. Zorlandığın ${weak.length} cümleyi doğru şekilde tekrar etmek ister misin?`,{resume:false,lang:'tr',voice:'F1'})}
function handleLessonResult(action){const lesson=state.planningLesson,themeId=lesson.themeId;if(action==='review')return startMistakeReview();if(action==='skip-review'){document.querySelector('.lesson-review-offer')?.remove();return showPlanningLessonCompletion()}if(action==='themes'){$('#changeTheme').click();return}if(action==='repeat'){stopPlanningLesson(false);return startPlanningLesson(themeId)}if(action==='exam'){stopPlanningLesson(false);state.planMode='exam';localStorage.setItem('planPracticeMode','exam');return beginSourceExam(themeId)}}
function selectTheme(themeId){state.selectedThemeId=themeId;state.exam=null;const theme=state.themes.find(x=>x.id===themeId);$('#themePicker').hidden=true;$('#practiceLayout').hidden=false;$('#pageTitle').textContent=theme?.title||'Gemeinsam etwas planen';renderThemePreview(theme);setAvatarBehavior('idle')}
