function getTtsAudioContext(){if(ttsAudioContext)return ttsAudioContext;const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return null;ttsAudioContext=new AudioContextClass();return ttsAudioContext}
function playLessonFeedbackTone(type='success'){if(state.speechMuted||state.paused)return;const context=getTtsAudioContext();if(!context)return;const play=()=>{const now=context.currentTime,notes=type==='success'?[660,880]:[210,165];notes.forEach((frequency,index)=>{const oscillator=context.createOscillator(),gain=context.createGain(),start=now+index*.075;oscillator.type=type==='success'?'sine':'triangle';oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(type==='success'?.12:.09,start+.018);gain.gain.exponentialRampToValueAtTime(.0001,start+.16);oscillator.connect(gain).connect(context.destination);oscillator.start(start);oscillator.stop(start+.18)})};if(context.state==='suspended')context.resume().then(play).catch(()=>{});else play()}
