async function speak(text,{resume=true,lang='de',voice=null}={}){if(!text||state.paused)return false;state.lastSpeech=text;if(state.speechMuted){stopSpeech(false);setVoiceState('','Ses kapalı');setAvatarBehavior('idle');return false}stopRecognition(false);stopSpeech(false);const id=ttsRequestId,c=selectedCharacter(),speechVoice=voice||c.voice,key=speechCacheKey(text,lang,speechVoice),nativeFast=localStorage.getItem('fastNativeVoice')==='true'&&'speechSynthesis'in window;setVoiceState('thinking',lang==='tr'?'Clara Türkçe anlatıyor':`${c.name} yüksek kaliteli sesi hazırlanıyor`);setAvatarBehavior(inferAvatarBehavior(text));if(nativeFast)return systemSpeak(text,resume,id,lang==='tr'?'tr-TR':'de-DE',lang==='tr'||state.character!=='lukas');try{currentTtsController=new AbortController();let blob=ttsCache.get(key);if(!blob){const r=await fetch('/api/tts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,voice:speechVoice,speed:lang==='tr'?.94:c.speed,lang}),signal:currentTtsController.signal});if(!r.ok)throw Error(`tts-${r.status}`);blob=await r.blob();ttsCache.set(key,blob);if(ttsCache.size>36)ttsCache.delete(ttsCache.keys().next().value)}if(id!==ttsRequestId)return false;await playTtsBlob(blob,text,id);if(id===ttsRequestId){currentTtsAudio=null;speechFinished(resume)}return true}catch(error){if(error?.name==='AbortError'||id!==ttsRequestId)return false;currentTtsController=null;console.warn('Yerel avatar sesi oynatılamadı',error);toast('Yüksek kaliteli yerel ses paketi hazır değil; cihazın çevrimdışı sesi kullanılıyor.');return systemSpeak(text,resume,id,lang==='tr'?'tr-TR':'de-DE',lang==='tr'||state.character!=='lukas')}}
