function ensureHeroAvatar(){const hero=$('.hero-portrait'),image=$('#tutorImage');if(!hero)return null;let clone=$('#heroAvatarRig');if(clone)return clone;const source=$('.avatar-stage .avatar-2d');if(!source)return null;clone=source.cloneNode(true);clone.id='heroAvatarRig';clone.classList.add('hero-avatar-rig');const idMap={};clone.querySelectorAll('[id]').forEach((el,i)=>{const old=el.id,next=`hero-${old}-${i}`;idMap[old]=next;el.id=next});clone.querySelectorAll('*').forEach(el=>{for(const attr of ['fill','stroke','filter','clip-path','mask','href','xlink:href']){const value=el.getAttribute(attr);if(!value)continue;let next=value;for(const [old,id] of Object.entries(idMap))next=next.replaceAll(`url(#${old})`,`url(#${id})`).replaceAll(`#${old}`,`#${id}`);if(next!==value)el.setAttribute(attr,next)}});hero.insertBefore(clone,image);image.hidden=true;return clone}
