const WORD_SCENES={clothingFit:['scenes',0],clothes:['scenes',1],rain:['scenes',2],snow:['scenes',3],sun:['scenes',4],nature:['scenes',4],health:['scenes',5],food:['scenes',6],drink:['scenes',7],train:['scenes',8],car:['scenes',9],bike:['scenes',10],travel:['scenes',11],sleep:['scenes',12],work:['scenes',13],study:['scenes',14],shopping:['scenes',15],phone:['scenes',16],home:['scenes',17],family:['scenes',18],friends:['scenes',19],sport:['scenes',20],animal:['scenes',21],music:['scenes',22],time:['scenes',23],conversation:['scenes',24],learningMoment:['scenes',24],open:['actions',0],close:['actions',1],giveGift:['actions',2],receiveParcel:['actions',3],wait:['actions',4],help:['actions',5],clean:['actions',6],cook:['actions',7],read:['actions',8],write:['actions',9],buy:['actions',10],pay:['actions',11],readLetter:['actions',12],walk:['actions',13],sit:['actions',14],stand:['actions',15],happy:['actions',16],sad:['actions',17],angry:['actions',18],bigSmall:['actions',19],fastSlow:['actions',20],fullEmpty:['actions',21],nearFar:['actions',22],agree:['actions',23],success:['actions',24],kitchen:['places',0],bathroom:['places',1],bedroom:['places',2],livingRoom:['places',3],office:['places',4],classroom:['places',5],supermarket:['places',6],hospital:['places',7],pharmacy:['places',8],bank:['places',9],postOffice:['places',10],station:['places',11],airport:['places',12],restaurant:['places',13],hotel:['places',14],park:['places',15],city:['places',16],village:['places',17],mountain:['places',18],sea:['places',19],book:['places',20],computer:['places',21],mobile:['places',22],gift:['places',23],calendar:['places',24]};
const WORD_SCENE_FILES={scenes:'assets/goethe-word-scenes-v1.png',actions:'assets/goethe-word-actions-v1.png',places:'assets/goethe-word-places-v1.png'},WORD_SCENE_POSITIONS=[1,25.5,50,74.5,99];
function wordVisual(card,compact=false){const scene=semanticWordScene(card),uniqueImage=state.wordImageManifest[card.id],[atlas,index]=WORD_SCENES[scene]||WORD_SCENES.study,column=index%5,row=Math.floor(index/5),x=WORD_SCENE_POSITIONS[column],y=WORD_SCENE_POSITIONS[row],description=`${card.word}: ${card.example}`;if(uniqueImage)return `<span class="word-scene-art unique${compact?' compact':''}" role="img" aria-label="${escapeHtml(description)}" data-scene="unique" style="--scene-image:url('${escapeHtml(uniqueImage)}')"></span>`;return `<span class="word-scene-art${compact?' compact':''}" role="img" aria-label="${escapeHtml(description)}" data-scene="${scene}" style="--scene-image:url('${WORD_SCENE_FILES[atlas]}');--scene-x:${x}%;--scene-y:${y}%"></span>`}
function translationKey(card){return `v4:${state.uiLang}:${card.id}`}
function cachedTranslation(card){const language=state.uiLang==='tr'?'tr':'en',packed=state.wordPacks[language]?.[card.id];if(Array.isArray(packed))return {meaning:packed[0],exampleTranslation:packed[1]};return packed?.meaning&&packed?.exampleTranslation?packed:null}
function wordBackCopy(){return state.uiLang==='tr'?{meaning:'KELİME ANLAMI',sentence:'CÜMLE ÇEVİRİSİ',hint:'Görsele dönmek için dokun'}:{meaning:'WORD MEANING',sentence:'SENTENCE TRANSLATION',hint:'Tap to return to the image'}}
function renderWords(){const card=currentWord(),parts=splitWord(card.word),translation=cachedTranslation(card),copy=wordCopy(),back=wordBackCopy(),missing=state.uiLang==='tr'?'Çeviri paketi hazırlanıyor.':'Translation pack is being prepared.';$('#wordVisual').innerHTML=`<div class="word-flip${state.wordFlipped?' is-flipped':''}" data-word-flip><div class="word-flip-inner"><div class="word-flip-face word-flip-front">${wordVisual(card)}<span>${state.uiLang==='tr'?'Anlamı görmek için görsele dokun':'Tap the image to see the meaning'}</span></div><div class="word-flip-face word-flip-back"><small>${back.meaning}</small><strong>${escapeHtml(translation?.meaning||missing)}</strong><small>${back.sentence}</small><p>${escapeHtml(translation?.exampleTranslation||'')}</p><em>${back.hint}</em></div></div></div>`;$('#wordArticle').textContent=parts.article;$('#wordArticle').style.visibility=parts.article?'visible':'hidden';$('#wordGerman').textContent=parts.main;$('#wordForms').textContent=card.forms&&card.forms!==card.word?card.forms:'';$('#wordExample').textContent=card.example;$('#wordSource').textContent=`${card.category} · PDF S. ${card.sourcePage}`;$('#wordAudio').textContent=`▶ ${copy.listen}`;$('#wordTotal').textContent=state.words.length.toLocaleString(state.uiLang);$('#wordTodayProgress').textContent=`${(state.word%state.wordSettings.count)+1} / ${state.wordSettings.count}`;$('#wordTranslation').hidden=true;$('#flashcard').classList.toggle('revealed',state.wordFlipped)}
async function speakWordCard(card=currentWord()){await speak(card.word,{resume:false});await new Promise(r=>setTimeout(r,850));await speak(card.example,{resume:false})}
async function translateWord(card=currentWord()){return cachedTranslation(card)||{meaning:state.uiLang==='tr'?'Çeviri paketi hazırlanıyor.':'Translation pack is being prepared.',exampleTranslation:''}}
function revealCurrentWord(){state.wordFlipped=!state.wordFlipped;renderWords()}
function applyWordLanguage(){if(!$('#wordPageTitle'))return;const copy=wordCopy();$('#wordPageTitle').textContent=copy.title;$('#wordPageText').textContent=copy.text;$('#wordLibraryLabel').textContent=copy.library;$('#wordProgressLabel').textContent=copy.today;$('#startQuickReview').textContent=`✦ ${copy.quick}`;$('#quickReviewSwipeHint').textContent=copy.hint;if(state.view==='words')renderWords()}
function saveWordSettings(){state.wordSettings.enabled=$('#quickReviewEnabled').checked;state.wordSettings.count=Number($('#dailyWordCount').value)||5;localStorage.setItem(WORD_PREF_KEY,JSON.stringify(state.wordSettings));$('#wordSettingsDialog').close();renderWords();toast(state.wordSettings.enabled?'Günlük hızlı tekrar açıldı.':'Günlük hızlı tekrar kapatıldı.')}
function openWordSettings(){ $('#quickReviewEnabled').checked=state.wordSettings.enabled;$('#dailyWordCount').value=String(state.wordSettings.count);$('#wordSettingsDialog').showModal() }
function quickMotivation(){return WORD_MOTIVATION[state.uiLang]||wordCopy().done}
function openQuickReview(force=false){if(!state.words.length||!force&&(!state.wordSettings.enabled||state.view!=='home'||state.started||state.exam||state.oral.part))return;const count=Math.min(state.wordSettings.count,state.words.length),start=state.word%state.words.length;state.quickReview={items:Array.from({length:count},(_,i)=>state.words[(start+i)%state.words.length]),index:0,flipped:false,lastShown:Date.now()};$('#quickReview').hidden=false;document.body.classList.add('quick-review-open');renderQuickReview()}
function closeQuickReview(){window.speechSynthesis?.cancel();$('#quickReview').hidden=true;document.body.classList.remove('quick-review-open')}
function renderQuickReview(){const review=state.quickReview,card=review.items[review.index];if(!card)return;const parts=splitWord(card.word),translation=cachedTranslation(card),copy=wordCopy();$('#quickReviewEyebrow').textContent=`${copy.today} · ${review.items.length} ${state.uiLang==='de'?'WÖRTER':'KELİME'}`;$('#quickReviewCounter').textContent=`${review.index+1} / ${review.items.length}`;$('#quickReviewProgress').style.width=`${(review.index+1)/review.items.length*100}%`;$('#quickReviewPrev').disabled=review.index===0;$('#quickReviewCard').innerHTML=`<article class="quick-word-card ${review.flipped?'flipped':''}" data-quick-audio>${wordVisual(card,true)}<small>${escapeHtml(card.category)}</small><span>${escapeHtml(parts.article)}</span><h2>${escapeHtml(parts.main)}</h2><p>${escapeHtml(card.example)}</p><button data-quick-flip>${escapeHtml(copy.reveal)}</button><div class="quick-word-translation" ${review.flipped?'':'hidden'}><b>${escapeHtml(translation?.meaning||copy.loading)}</b><p>${escapeHtml(translation?.exampleTranslation||'')}</p></div></article>`;if(review.flipped&&!translation)translateQuickWord(card)}
async function translateQuickWord(card){const value=await translateWord(card);if(state.quickReview.items[state.quickReview.index]?.id!==card.id)return;const box=$('.quick-word-translation');if(box){box.querySelector('b').textContent=value.meaning;box.querySelector('p').textContent=value.exampleTranslation}}
function flipQuickReview(){state.quickReview.flipped=true;renderQuickReview()}
function moveQuickReview(direction){const review=state.quickReview;if(direction<0&&review.index>0){review.index--;review.flipped=false;return renderQuickReview()}if(direction>0&&review.index<review.items.length-1){review.index++;review.flipped=false;state.word=(state.word+1)%state.words.length;return renderQuickReview()}if(direction>0){$('#quickReviewCard').innerHTML=`<div class="quick-review-done"><span>✓</span><h2>${escapeHtml(quickMotivation())}</h2></div>`;$('#quickReviewNext').disabled=true;setTimeout(closeQuickReview,1900)}}
function renderGrammar(){$('#grammarGrid').innerHTML=GRAMMAR.map(g=>`<article class="grammar-card"><small>B1 · KONU ${GRAMMAR.indexOf(g)+1}</small><h3>${g[0]}</h3><p>${g[1]}</p><blockquote>${g[2]}</blockquote><button data-go="practice">Clara ile uygula →</button></article>`).join('')}
function renderLibrary(){const list=$('#libraryList');list.innerHTML=state.library.length?state.library.map(f=>`<article class="file-row"><span>${escapeHtml(f.type.toUpperCase())}</span><div><b>${escapeHtml(f.name)}</b><small>${escapeHtml(f.size)} · ${f.chars?`${f.chars.toLocaleString('tr-TR')} karakter · ${f.themes||0} tema`:'hazır'}</small></div><em>✓ Kaynak kilitli</em></article>`).join(''):'<article class="file-row"><span>PDF</span><div><b>Henüz sınav kaynağı yüklenmedi</b><small>A/B veya Partner konuşmaları bulunan PDF’nizi ekleyin.</small></div><em>Bekliyor</em></article>'}
async function refreshLibrary(){try{const r=await fetch('/api/library');if(r.ok)state.library=await r.json()}catch{}renderLibrary()}
async function uploadFiles(files){for(const file of files){toast(`${file.name} içindeki temalar ayrılıyor…`);const base64=await new Promise((ok,fail)=>{const r=new FileReader();r.onload=()=>ok(r.result.split(',')[1]);r.onerror=fail;r.readAsDataURL(file)});try{const res=await fetch('/api/library',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file.name,type:file.name.split('.').pop(),size:file.size,data:base64})});const item=await res.json();if(!res.ok)throw new Error(item.error);toast(`${item.themes} sınav teması kaynağa bağlandı.`)}catch(error){toast(error.message||'PDF işlenemedi.')}}await refreshLibrary()}
const formatBytes=n=>{n=Number(n)||0;if(n<1024)return `${n} B`;if(n<1024**2)return `${(n/1024).toFixed(1)} KB`;if(n<1024**3)return `${(n/1024**2).toFixed(1)} MB`;return `${(n/1024**3).toFixed(1)} GB`};
function renderSkills(){const skills=[['Akıcılık',74],['Kelime çeşitliliği',68],['Gramer doğruluğu',71],['Telaffuz',82],['Etkileşim',78]];$('#skillBars').innerHTML=skills.map(([n,v])=>`<div class="skill-row"><span>${n}</span><i><u style="width:${v}%"></u></i><b>${v}</b></div>`).join('')}

let localModelCatalog=[];
function renderModelCatalog(data){
  localModelCatalog=data.models||[];
  const installedIds=new Set(localModelCatalog.filter(x=>x.installed).map(x=>x.id));
  if(!installedIds.has($('#modelName').value)){const fallback=installedIds.has(data.suggested)?data.suggested:localModelCatalog.find(x=>x.installed)?.id;if(fallback){$('#modelName').value=fallback;state.settings.model=fallback;localStorage.setItem('modelName',fallback)}}
  const memory=formatBytes(data.memory),suggested=localModelCatalog.find(x=>x.id===data.suggested);
  $('#deviceAdvice').innerHTML=`<b>${escapeHtml(data.runtime)} hazır</b><span>${escapeHtml(data.platform)} · ${escapeHtml(memory)} RAM · Önerilen: ${escapeHtml(suggested?.title||'Temel model')}</span>`;
  $('#modelCatalog').innerHTML=localModelCatalog.map(model=>{
    const active=model.installed&&model.id===$('#modelName').value,action=model.installed?(active?'active':'activate'):'pull';
    const label=action==='active'?'✓ Aktif':action==='activate'?'Etkinleştir':model.rank===0?'Temel modeli indir':'Yükselt ve indir';
    return `<article class="model-pack ${active?'active':''}" data-tier="${model.tier}"><div class="model-pack-title"><span>${escapeHtml(model.title)}</span>${model.id===data.suggested?'<em>Bu cihaz için önerilen</em>':''}</div><p>${escapeHtml(model.description)}</p><small>${escapeHtml(model.device)}${model.size?` · ${escapeHtml(formatBytes(model.size))}`:''}</small><div class="model-pack-actions"><b>${model.installed?'Cihazda kurulu':'İndirilmeye hazır'}</b><button type="button" data-model-action="${action}" data-model-id="${escapeHtml(model.id)}" ${action==='active'?'disabled':''}>${label}</button>${model.installed&&!active?`<button type="button" class="model-delete" data-model-action="delete" data-model-id="${escapeHtml(model.id)}">Sil</button>`:''}</div></article>`
  }).join('');
}
async function refreshModelCatalog(){
  const box=$('#modelCatalog');if(!box)return;
  box.innerHTML='<div class="model-catalog-empty">Yerel modeller kontrol ediliyor…</div>';
  try{const r=await fetch('/api/models/catalog',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ollamaUrl:$('#ollamaUrl').value})}),data=await r.json();if(!r.ok)throw Error(data.error||'Ollama kullanılamıyor');renderModelCatalog(data)}catch(error){$('#deviceAdvice').innerHTML='<b>Ollama bağlantısı bekleniyor</b><span>Masaüstünde Ollama’yı açın. Mobil sürüm aynı paketleri yerel mobil motorla yönetecek.</span>';box.innerHTML=`<div class="model-catalog-empty"><b>Model kataloğu açılamadı.</b><span>${escapeHtml(error.message)}</span><button type="button" data-model-action="refresh">Tekrar dene</button></div>`}
}
async function manageLocalModel(action,model){
  if(action==='refresh')return refreshModelCatalog();
  if(action==='activate'){$('#modelName').value=model;state.settings.model=model;localStorage.setItem('modelName',model);toast(`${model} etkinleştirildi.`);return refreshModelCatalog()}
  if(action==='delete'&&!confirm(`${model} modelini bu cihazdan silmek istiyor musunuz?`))return;
  const box=$('#modelCatalog'),verb=action==='pull'?'indiriliyor':'siliniyor';box.classList.add('busy');$('#deviceAdvice').innerHTML=`<b>${escapeHtml(model)} ${verb}…</b><span>Bu pencereyi kapatmayın. Büyük modeller birkaç dakika sürebilir.</span>`;
  try{const r=await fetch(`/api/models/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ollamaUrl:$('#ollamaUrl').value,model})}),data=await r.json();if(!r.ok)throw Error(data.error||'Paket işlemi tamamlanamadı');if(action==='pull'){$('#modelName').value=model;state.settings.model=model;localStorage.setItem('modelName',model)}toast(action==='pull'?`${model} indirildi ve etkinleştirildi.`:`${model} silindi.`)}catch(error){toast(error.message)}finally{box.classList.remove('busy');await refreshModelCatalog()}
}

